router=APIRouter(tags=["Procurement"])
def svc(cls,s,a,r): return cls(s,a,r.client.host if r.client else None,r.headers.get("user-agent"))
async def history(session,kind,id):
    rows=list((await session.scalars(select(AuditLog).where(AuditLog.entity_type==kind,AuditLog.entity_id==id).order_by(AuditLog.created_at))).all()); return APIResponse(data=[{"action":x.action,"actor_user_id":str(x.actor_user_id) if x.actor_user_id else None,"metadata":x.metadata_json,"created_at":x.created_at.isoformat()} for x in rows])
def pdf_file(number,title,status,rows,total=None): path=ProcurementPDFService().generate(number,title,status,rows,total); return FileResponse(path,media_type="application/pdf",filename=path.name)

