    if not x: raise NotFoundError("Purchase order not found","PURCHASE_ORDER_NOT_FOUND")
    rows=[["Product","Qty","Unit cost","GST","Line total"]]+[[str(i.product_id),str(i.ordered_quantity),str(i.unit_cost),f"{i.gst_rate}%",str(i.line_total)] for i in x.items]; return pdf_file(x.po_number,"PURCHASE ORDER",x.status.value,rows,f"Grand Total: {x.currency_code} {x.grand_total}")

