@router.get("/procurement/analytics/{report}",response_model=APIResponse[dict])
async def analytics(report:str,request:Request,session:DatabaseSession,actor:User=Depends(require_permission("procurement.analytics"))):
    if report not in {"purchases","suppliers","outstanding","delivery-performance","purchase-returns"}: raise NotFoundError("Procurement report not found","PROCUREMENT_REPORT_NOT_FOUND")
    data=await svc(ProcurementAnalyticsService,session,actor,request).dashboard(); return APIResponse(data={"report":report,**data})
